def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)

    # Stay inside the arena bubble
    r = (me.x * me.x + me.y * me.y) ** 0.5
    if r > 5.6:
        cbrg = bearing_to(0, 0)
        if abs(cbrg) > 10:
            t = 1.0 if cbrg > 0 else -1.0
            return (-t, t)
        return (1.0, 1.0)

    # Spin in place to try to break a clamp
    if me.held:
        return (1.0, -1.0)

    # Keep the front spinner pointed at the enemy
    brg = bearing_to(enemy.x, enemy.y)
    if abs(brg) > 20:
        t = 1.0 if brg > 0 else -1.0
        return (-t, t)

    # Charge in with the spinner
    return (1.0, 1.0)


